#include "lexer.hpp"
#include <fstream>
#include <iterator>
#include <cstdarg>
#include <cstring>
#include <cctype>
#include "util.hpp"

std::string blitz::token::to_string() const
{
	std::string name;
	switch (type) {
	case variant::UNKNOWN:
		name = "Unknown";
		break;
	case variant::ENDOFFILE:
		name = "EndOfFile";
		break;
	case variant::NEWLINE:
		name = "NewLine";
		break;
	case variant::SEPARATOR:
		name = "Separator";
		break;
	case variant::CONTROL:
		name = "Control";
		break;
	case variant::COMMENT:
		name = "Comment";
		break;
	case variant::TEXT:
		name = "Text";
		break;
	case variant::STRING:
		name = "String";
		break;
	case variant::INTEGER:
		name = "Integer";
		break;
	case variant::REAL:
		name = "Real";
		break;
	case variant::SYMBOL:
		name = "Symbol";
		break;
	default:
		name = "Invalid";
		break;
	}

	if (type == variant::NEWLINE || type == variant::CONTROL) {
		return blitz::format("%s(%llu@%llu, %d)", name.c_str(), location.first, location.second, text[0]);
	} else {
		return blitz::format("%s(%llu@%llu, %s)", name.c_str(), location.first, location.second, text.c_str());
	}
}

bool blitz::token::operator==(variant rhs) const
{
	return type == rhs;
}

bool blitz::token::operator==(std::string const& rhs) const
{
	return text == rhs;
}

blitz::lexer::~lexer() {}

blitz::lexer::lexer(std::filesystem::path file) : _file(file), _data(), _offset(0), _text_end(size_t(-1)), _location{ 1, 1 }
{
	// We read the entire file up front: Blitz source files are small, and it makes saving/restoring state trivial.
	std::ifstream stream(_file, std::ios_base::binary);
	if (!stream.good()) {
		throw std::runtime_error(blitz::format("Reading file '%s' failed.", file.generic_string().c_str()));
	}
	_data.assign(std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>());

	// Skip a UTF-8 byte order mark if there is one.
	if ((_data.size() >= 3) && (_data.compare(0, 3, "\xEF\xBB\xBF") == 0)) {
		_offset = 3;
	}

	_next = _current = blitz::token{
		.location = { 0, 0 },
		.text     = "",
		.type     = token::variant::NONE,
	};
}

blitz::lexer::state blitz::lexer::save_state()
{
	return state{ _offset, _location, _current, _next };
}

void blitz::lexer::load_state(blitz::lexer::state state)
{
	_offset   = state.offset;
	_location = state.location;
	_current  = state.current;
	_next     = state.next;
}

blitz::token blitz::lexer::current()
{
	return _current;
}

blitz::token blitz::lexer::next()
{
	_current = peek();
	_next    = blitz::token{
		   .location = { 0, 0 },
		   .text     = "",
		   .type     = token::variant::NONE,
	};
	return _current;
}

blitz::token blitz::lexer::peek()
{
	if (_next.type == blitz::token::variant::NONE) {
		_next = scan();
	}
	return _next;
}

std::filesystem::path blitz::lexer::file()
{
	return std::filesystem::path(_file);
}

blitz::token blitz::lexer::scan()
{
	auto at = [&](size_t off = 0) -> int {
		return (_offset + off < _data.size()) ? (unsigned char)_data[_offset + off] : EOF;
	};
	auto advance = [&](size_t count = 1) {
		_offset += count;
		_location.second += count;
	};
	auto is_digit = [](int c) { return (c >= '0') && (c <= '9'); };
	auto is_hex   = [](int c) { return ((c >= '0') && (c <= '9')) || ((c >= 'a') && (c <= 'f')) || ((c >= 'A') && (c <= 'F')); };
	auto is_ident_start = [](int c) { return ((c >= 'a') && (c <= 'z')) || ((c >= 'A') && (c <= 'Z')) || (c == '_') || (c >= 0x80); };
	auto is_ident = [&](int c) { return is_ident_start(c) || is_digit(c); };

	// Skip white space, which carries no meaning.
	while (blitz::utility::is_white_space(at())) {
		advance();
	}

	blitz::token token{ .location = _location, .text = "", .type = blitz::token::variant::UNKNOWN };
	int          chr = at();

	if (chr == EOF) {
		token.type = blitz::token::variant::ENDOFFILE;
	} else if ((chr == '\r') || (chr == '\n')) {
		token.type = blitz::token::variant::NEWLINE;
		token.text = "\n";
		_offset++;
		if ((chr == '\r') && (at() == '\n')) {
			_offset++;
		}
		_location.first++;
		_location.second = 1;
	} else if (chr == ';') {
		// A comment, which ends at the next new line.
		token.type = blitz::token::variant::COMMENT;
		advance();
		size_t start = _offset;
		while ((at() != EOF) && (at() != '\r') && (at() != '\n')) {
			advance();
		}
		token.text = _data.substr(start, _offset - start);
	} else if (chr == ':') {
		// Command separator, allows code writers to pretend it's all one line!
		token.type = blitz::token::variant::SEPARATOR;
		token.text = ":";
		advance();
	} else if (is_digit(chr) || ((chr == '.') && is_digit(at(1)))) {
		// Integer or Real
		token.type   = blitz::token::variant::INTEGER;
		size_t start = _offset;
		bool   prefixed = (chr == '0') && ((at(1) == 'x') || (at(1) == 'X') || (at(1) == 'b') || (at(1) == 'B'));
		if ((chr == '0') && ((at(1) == 'x') || (at(1) == 'X'))) {
			advance(2);
			while (is_hex(at())) {
				advance();
			}
		} else if ((chr == '0') && ((at(1) == 'b') || (at(1) == 'B'))) {
			advance(2);
			while ((at() == '0') || (at() == '1')) {
				advance();
			}
		} else {
			while (is_digit(at())) {
				advance();
			}
			// `1.5`, and also `1.` which is a Real too, as long as nothing that could be a name follows.
			if ((at() == '.') && (is_digit(at(1)) || !is_ident_start(at(1)))) {
				token.type = blitz::token::variant::REAL;
				advance();
				while (is_digit(at())) {
					advance();
				}
			}
		}
		// A suffix that says the exact type: u, i8..i64 and ui8..ui64 for whole numbers, h, f, d and fp16..fp64 for decimal numbers. It has to end
		// the number (`1foo` stays a number and a name), and the float ones are not for 0x and 0b numbers, as `f` and `d` are digits there.
		bool whole = (token.type == blitz::token::variant::INTEGER);
		static const struct {
			const char* text;
			bool        whole;
		} suffixes[] = { { "ui64", true }, { "ui32", true }, { "ui16", true }, { "ui8", true }, { "i64", true }, { "i32", true }, { "i16", true }, { "i8", true },
		                 { "u", true },    { "fp64", false }, { "fp32", false }, { "fp16", false }, { "h", false },   { "f", false },   { "d", false } };
		for (auto const& suffix : suffixes) {
			if ((suffix.whole && !whole) || (!suffix.whole && prefixed)) {
				continue;
			}
			size_t length = strlen(suffix.text);
			bool   match  = true;
			for (size_t idx = 0; idx < length; idx++) {
				match = match && (tolower(at(idx)) == suffix.text[idx]);
			}
			if (match && !is_ident(at(length))) {
				advance(length);
				break;
			}
		}
		token.text = _data.substr(start, _offset - start); // A name can follow right away, like in `Case 1Foo()`.
	} else if (is_ident_start(chr)) {
		token.type   = blitz::token::variant::TEXT;
		size_t start = _offset;
		while (is_ident(at())) {
			advance();
		}
		token.text = _data.substr(start, _offset - start);
		_text_end  = _offset;
	} else if (((chr == '$') && is_hex(at(1)) && (_offset != _text_end)) || ((chr == '%') && ((at(1) == '0') || (at(1) == '1')) && (_offset != _text_end))) {
		// `$FF00FF` and `%1010` are numbers, unless they follow a name, where they say what type that is.
		bool hex = (chr == '$');
		advance();
		size_t start = _offset;
		while (hex ? is_hex(at()) : ((at() == '0') || (at() == '1'))) {
			advance();
		}
		token.type = blitz::token::variant::INTEGER;
		token.text = std::string(hex ? "$" : "%") + _data.substr(start, _offset - start); // Kept apart from 0x and 0b, as these wrap around instead of becoming unsigned.
		if (hex && (at() == '$')) {
			advance(); // A stray type character behind the number, which Blitz allows.
		}
	} else if (chr == '"') {
		// Strings have no escape sequences in Blitz; a string ends at the next quote.
		token.type = blitz::token::variant::STRING;
		advance();
		size_t start = _offset;
		while ((at() != '"') && (at() != EOF) && (at() != '\r') && (at() != '\n')) {
			advance();
		}
		token.text = _data.substr(start, _offset - start);
		if (at() == '"') {
			advance();
		} // Blitz lets a string end with the line, so a missing closing quote is fine.
	} else if (chr < 32) {
		token.type = blitz::token::variant::CONTROL;
		token.text = std::string(1, char(chr));
		advance();
	} else if (blitz::utility::is_symbol(chr)) {
		token.type = blitz::token::variant::SYMBOL;
		int nxt     = at(1);
		if (((chr == '=') && ((nxt == '>') || (nxt == '<'))) || ((chr == '>') && (nxt == '<'))) {
			// `=>`, `=<` and `><` are other ways to write `>=`, `<=` and `<>`.
			token.text = (chr == '>') ? "<>" : ((nxt == '>') ? ">=" : "<=");
			advance(2);
		} else if (((chr == '<') && ((nxt == '>') || (nxt == '='))) || ((chr == '>') && (nxt == '=')) || ((chr == '=') && (nxt == '=')) || ((chr == '%') && (nxt == '%')) || ((chr == '#') && (nxt == '#'))) {
			token.text = { char(chr), char(nxt) };
			advance(2);
		} else {
			token.text = std::string(1, char(chr));
			advance();
		}
	} else {
		throw blitz::error(_file, _location, _location, blitz::format("Unexpected character '%c' (0x%02x).", (chr >= 32 && chr < 127) ? char(chr) : '?', chr));
	}
	return token;
}
